fn archive(paths:&[PathBuf],base:&Path,out:&Path)->Value{let mut map=BTreeMap::new();for p in paths{let bytes=fs::read(p).unwrap();let entry=match String::from_utf8(bytes.clone()){Ok(s)=>json!({"sha256":hash(p),"bytes":bytes.len(),"utf8":s}),Err(_)=>json!({"sha256":hash(p),"bytes":bytes.len(),"hex":bytes.iter().map(|b|format!("{b:02x}")).collect::<String>()})};map.insert(p.strip_prefix(base).unwrap().display().to_string(),entry);}let bytes=serde_json::to_vec(&map).unwrap();let tmp=out.with_extension("json");fs::write(&tmp,&bytes).unwrap();let file=fs::File::create(out).unwrap();assert!(Command::new("gzip").args(["-n","-c"]).arg(&tmp).stdout(Stdio::from(file)).status().unwrap().success());let back=Command::new("gzip").args(["-dc"]).arg(out).output().unwrap();assert!(back.status.success());assert_eq!(back.stdout,bytes);let back:Value=serde_json::from_slice(&back.stdout).unwrap();for p in paths{let e=&back[p.strip_prefix(base).unwrap().to_str().unwrap()];let b=if let Some(s)=e["utf8"].as_str(){s.as_bytes().to_vec()}else{let s=e["hex"].as_str().unwrap();(0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap()).collect()};assert_eq!(b,fs::read(p).unwrap());}fs::remove_file(tmp).unwrap();json!({"members":paths.len(),"sha256":hash(out),"roundtrip_exact":true})}
